# Recalculate with correct formula:
# For each input row, if non-1 at col c with value v:
# - If c is even: for each col j in 0..c: even parity j gets v, odd parity j gets 5
# - If c is odd: for each col j in 0..c: odd parity j gets v, even parity j gets 5

def apply_rule_2(input_row, W=5):
    output = [1 for _ in range(W)]
    cols_valffected_1 = [(j, inp[j]) for j, inp in enumerate(input_row) if inp != 1]
    if not cols_valffected_1:
        return output

    c, v = cols_valffected_1[0]  # should be only one non-1

    for j in range(c + 1):
        if j == c:
            output[j] = v
        elif j % 2 == c % 2:
            output[j] = v
        else:
            output[j] = 5

    return output

# Verify against all demos
H, W = 15, 5
for i in range(H):
    inp = input_demo[i]
    out = output_demo[i]
    pred = apply_rule_2(inp, W)
    match = pred == out
    if not match:
        print(f"FAIL row {i}: {inp} -> {out}, pred={pred}")
    else:
        print(f"OK row {i}: {inp} -> {out}")

print("\nAll match!" if all(apply_rule_2(input_demo[i], 5) == output_demo[i] for i in range(15)) else "Some failed")

